#pragma once
#include "fur_launch_configuration_candidate.h"
#include <windows.h>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <limits>
#include <atomic>
#include "fur_model_identity_candidate.h"
inline std::string encodeFurSettingsCandidate(const Graph&g,const FurLaunchConfigurationCandidate&c){
 validateFurLaunchConfigurationCandidate(c);auto asset=furModelAssetCandidate(g,c.model);auto uuid=furModelUuidCandidate(g.elements.at(c.model));size_t matches=0;for(const auto&e:g.elements)matches+=furModelUuidCandidate(e)==uuid;if(matches!=1)throw std::runtime_error("ambiguous fur model UUID");
 std::ostringstream out;out.imbue(std::locale::classic());out<<"SFM64_FUR_SETTINGS 2\n"<<uuid<<'\n'<<std::quoted(asset)<<'\n'<<c.count<<' '<<std::setprecision(std::numeric_limits<float>::max_digits10)<<c.length<<' '<<c.width<<' '<<unsigned(c.color[0])<<' '<<unsigned(c.color[1])<<' '<<unsigned(c.color[2])<<' '<<c.seed<<' '<<c.workers<<' '<<unsigned(c.coverage)<<'\n';auto text=out.str();if(text.size()>65536||text.find('\0')!=std::string::npos)throw std::runtime_error("fur settings too large/invalid");return text;
}
inline FurLaunchConfigurationCandidate decodeFurSettingsCandidate(const Graph&g,const std::string&text){
 if(text.size()>65536||text.find('\0')!=std::string::npos)throw std::runtime_error("invalid fur settings size/content");std::istringstream in(text);in.imbue(std::locale::classic());std::string magic,version,uuid,asset;in>>magic>>version>>uuid;in>>std::ws;if(in.peek()!='"')throw std::runtime_error("fur asset must be quoted");in>>std::quoted(asset);
 if(!in||magic!="SFM64_FUR_SETTINGS"||(version!="1"&&version!="2")||uuid.size()!=32||uuid.find_first_not_of("0123456789abcdef")!=std::string::npos)throw std::runtime_error("invalid fur settings header");
 auto token=[&](){std::string value;if(!(in>>value))throw std::runtime_error("incomplete fur settings");return value;};FurLaunchConfigurationCandidate c{};c.count=parseFurLaunchNumberCandidate<uint32_t>(token().c_str());c.length=parseFurLaunchNumberCandidate<float>(token().c_str());c.width=parseFurLaunchNumberCandidate<float>(token().c_str());for(auto&component:c.color){auto value=parseFurLaunchNumberCandidate<uint32_t>(token().c_str());if(value>255)throw std::runtime_error("invalid fur color");component=static_cast<uint8_t>(value);}c.seed=parseFurLaunchNumberCandidate<uint64_t>(token().c_str());c.workers=parseFurLaunchNumberCandidate<size_t>(token().c_str());if(version=="2"){auto value=parseFurLaunchNumberCandidate<unsigned>(token().c_str());if(value>1)throw std::runtime_error("invalid fur coverage");c.coverage=value!=0;}in>>std::ws;if(!in.eof())throw std::runtime_error("trailing fur settings");validateFurLaunchConfigurationCandidate(c);
 size_t matches=0;for(uint32_t i=0;i<g.elements.size();++i)if(furModelUuidCandidate(g.elements[i])==uuid){c.model=i;++matches;}if(matches!=1||furModelAssetCandidate(g,c.model)!=asset)throw std::runtime_error("fur settings model UUID/asset mismatch");return c;
}
inline FurLaunchConfigurationCandidate loadFurSettingsCandidate(const Graph&g,const std::filesystem::path&path){if(std::filesystem::file_size(path)>65536)throw std::runtime_error("fur settings too large");std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("fur settings open failed");std::string text(65537,0);in.read(text.data(),static_cast<std::streamsize>(text.size()));text.resize(static_cast<size_t>(in.gcount()));if(in.bad())throw std::runtime_error("fur settings read failed");return decodeFurSettingsCandidate(g,text);}
inline void saveFurSettingsCandidate(const Graph&g,const FurLaunchConfigurationCandidate&c,const std::filesystem::path&target){
 auto text=encodeFurSettingsCandidate(g,c);if(target.empty()||std::filesystem::exists(target))throw std::runtime_error("fur settings output exists or is empty");auto parent=target.parent_path();if(parent.empty())parent=".";static std::atomic<uint64_t>serial{0};std::filesystem::path staging;for(unsigned attempt=0;attempt<64;++attempt){auto candidate=parent/(".sfm64-fur-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64())+"-"+std::to_string(serial++));if(std::filesystem::create_directory(candidate)){staging=candidate;break;}}if(staging.empty())throw std::runtime_error("fur settings staging failed");auto file=staging/"settings";HANDLE handle=INVALID_HANDLE_VALUE;auto cleanup=[&](){if(handle!=INVALID_HANDLE_VALUE){CloseHandle(handle);handle=INVALID_HANDLE_VALUE;}std::error_code ec;std::filesystem::remove(file,ec);std::filesystem::remove(staging,ec);};
 try{handle=CreateFileW(file.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(handle==INVALID_HANDLE_VALUE)throw std::runtime_error("fur settings create failed");DWORD written=0;if(!WriteFile(handle,text.data(),static_cast<DWORD>(text.size()),&written,nullptr)||written!=text.size()||!FlushFileBuffers(handle))throw std::runtime_error("fur settings write/flush failed");if(!CloseHandle(handle)){handle=INVALID_HANDLE_VALUE;throw std::runtime_error("fur settings close failed");}handle=INVALID_HANDLE_VALUE;if(!MoveFileExW(file.c_str(),target.c_str(),MOVEFILE_WRITE_THROUGH))throw std::runtime_error("fur settings publish failed; refusing overwrite");cleanup();}catch(...){cleanup();throw;}
}
